// Helper function to remove Vietnamese tones for search
const removeVietnameseTones = (str: string) => {
  str = str.replace(/à|á|ạ|ả|ã|â|ầ|ấ|ậ|ẩ|ẫ|ă|ằ|ắ|ặ|ẳ|ẵ/g, "a");
  str = str.replace(/è|é|ẹ|ẻ|ẽ|ê|ề|ế|ệ|ể|ễ/g, "e");
  str = str.replace(/ì|í|ị|ỉ|ĩ/g, "i");
  str = str.replace(/ò|ó|ọ|ỏ|õ|ô|ồ|ố|ộ|ổ|ỗ|ơ|ờ|ớ|ợ|ở|ỡ/g, "o");
  str = str.replace(/ù|ú|ụ|ủ|ũ|ư|ừ|ứ|ự|ử|ữ/g, "u");
  str = str.replace(/ỳ|ý|ỵ|ỷ|ỹ/g, "y");
  str = str.replace(/đ/g, "d");
  str = str.replace(/À|Á|Ạ|Ả|Ã|Â|Ầ|Ấ|Ậ|Ẩ|Ẫ|Ă|Ằ|Ắ|Ặ|Ẳ|Ẵ/g, "A");
  str = str.replace(/È|É|Ẹ|Ẻ|Ẽ|Ê|Ề|Ế|Ệ|Ể|Ễ/g, "E");
  str = str.replace(/Ì|Í|Ị|Ỉ|Ĩ/g, "I");
  str = str.replace(/Ò|Ó|Ọ|Ỏ|Õ|Ô|Ồ|Ố|Ộ|Ổ|Ỗ|Ơ|Ờ|Ớ|Ợ|Ở|Ỡ/g, "O");
  str = str.replace(/Ù|Ú|Ụ|Ủ|Ũ|Ư|Ừ|Ứ|Ự|Ử|Ữ/g, "U");
  str = str.replace(/Ỳ|Ý|Ỵ|Ỷ|Ỹ/g, "Y");
  str = str.replace(/Đ/g, "D");
  str = str.replace(/\u0300|\u0301|\u0303|\u0309|\u0323/g, "");
  str = str.replace(/\u02C6|\u0306|\u031B/g, "");
  return str;
};

// State cho tìm vị trí theo tên
const [searchName, setSearchName] = useState("");
const [searchResult, setSearchResult] = useState<null | { index: number, cccd: any }>(null);

// Gợi ý tên từ queueData, bao gồm cả vị trí
const queueListForSearch = Object.values(queueData || {});
const nameOptions = queueListForSearch
  .map((item: any, idx: number) => ({
    value: item.Name,
    label: `${item.Name} (Vị trí: ${idx + 1})`,
    index: idx + 1,
    cccd: item
  }))
  .filter((item, i, arr) => item.value && arr.findIndex(t => t.value === item.value) === i);

{/* Input tìm vị trí theo tên */}
<AutoComplete
  options={nameOptions}
  filterOption={(inputValue, option) => {
    const normalizedInput = removeVietnameseTones(inputValue).toLowerCase();
    const normalizedOption = removeVietnameseTones(option?.value || '').toLowerCase();
    return normalizedOption.includes(normalizedInput);
  }}
  value={searchName}
  onChange={setSearchName}
  onSelect={val => setSearchName(val)}
  style={{ flex: 1, minWidth: 180 }}
  placeholder="Nhập tên cần tìm..."
  onKeyDown={e => {
    if (e.key === 'Enter') {
      const list = Object.values(queueData || {});
      const normalizedSearch = removeVietnameseTones(searchName.trim()).toLowerCase();
      const idx = list.findIndex(
        (item: any) => removeVietnameseTones((item.Name || "").trim()).toLowerCase() === normalizedSearch
      );
      if (idx >= 0) setSearchResult({ index: idx + 1, cccd: list[idx] });
      else setSearchResult(null);
    }
  }}
>
  <Input suffix={<SearchOutlined style={{ color: '#bfbfbf' }} />} />
</AutoComplete>
<Button
  onClick={() => {
    const list = Object.values(queueData || {});
    const normalizedSearch = removeVietnameseTones(searchName.trim()).toLowerCase();
    const idx = list.findIndex(
      (item: any) => removeVietnameseTones((item.Name || "").trim()).toLowerCase() === normalizedSearch
    );
    if (idx >= 0) setSearchResult({ index: idx + 1, cccd: list[idx] });
    else setSearchResult(null);
  }}
  type="default"
  disabled={!searchName.trim()}
  icon={<SearchOutlined />}
>
  Tìm
</Button>
